INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1035b50b-715f-486a-ba98-61346d69a728', 'fd38dbd3-7322-4f4c-86b4-f455ee3683c4', 0, 'The request is denied — AWS policy evaluation combines ALL applicable policies (identity-based AND resource-based, like a bucket policy) into one evaluation, and an explicit Deny in ANY applicable policy always overrides an Allow anywhere else in the evaluation, regardless of how broad or specific the Allow is.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46e88bed-1014-4e6c-9142-4f26ed98dea0', 'fd38dbd3-7322-4f4c-86b4-f455ee3683c4', 1, 'The request is allowed, since an identity-based policy always takes precedence over a resource-based bucket policy regardless of its content.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82159ffd-5360-4b21-8425-7d629aaf33de', 'fd38dbd3-7322-4f4c-86b4-f455ee3683c4', 2, 'The request is allowed, since bucket policies can only grant additional access and are structurally incapable of denying access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2150519f-fbaf-451c-9e89-a63f64091a21', 'fd38dbd3-7322-4f4c-86b4-f455ee3683c4', 3, 'AWS policy evaluation ignores resource-based policies entirely whenever an identity-based policy exists for the same principal.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fbb83ce-f321-43c3-a07f-8c1f95eec2ce', '6a38026b-87c8-4aa6-8000-bba92b03f2d4', 0, 'A VPC endpoint policy — a resource-based policy attached directly to the endpoint itself, controlling which AWS resources and actions can be reached THROUGH that specific endpoint, separate from and in addition to any IAM identity policy or bucket policy governing the same access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d29aa5b-b2e1-4b1e-90dc-41f26b5a8b36', '6a38026b-87c8-4aa6-8000-bba92b03f2d4', 1, 'A Network ACL, since NACLs are the mechanism that restricts a VPC endpoint to a single specific S3 bucket.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2e7eb11-22a8-4e0a-9559-cfcc5773516f', '6a38026b-87c8-4aa6-8000-bba92b03f2d4', 2, 'A security group, since security groups can be attached directly to a Gateway VPC Endpoint to restrict it to one bucket.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e6ad2d99-875e-4da8-b6ef-d5fcb7b0a250', '6a38026b-87c8-4aa6-8000-bba92b03f2d4', 3, 'A Gateway VPC Endpoint cannot be restricted to a specific bucket; once created it always permits access to every bucket in every account.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b78cf78-4d9e-4178-b0fd-ca8cf38cd054', '8e320165-2504-4efe-83c0-0d95c0feb0e0', 0, 'A KMS grant — a mechanism for programmatically delegating specific, limited permissions on a KMS key to a specific principal for a specific purpose, without modifying the key policy itself; grants can be created and revoked (or allowed to expire) independently and are commonly used by AWS services needing temporary, scoped access to a customer''s key on the customer''s behalf.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7490a3e-0bb2-41ab-9227-730ce978356a', '8e320165-2504-4efe-83c0-0d95c0feb0e0', 1, 'A security group, since security groups are the standard mechanism for granting temporary, scoped permissions on a KMS key.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24184f4d-1896-41e0-ab90-b70da0c239ed', '8e320165-2504-4efe-83c0-0d95c0feb0e0', 2, 'A Network ACL, since NACLs grant fine-grained, temporary KMS key permissions to specific principals.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ef2081c-534d-44f5-8f12-c94d3d9e6eb2', '8e320165-2504-4efe-83c0-0d95c0feb0e0', 3, 'KMS key policies are the only permission mechanism KMS supports; there is no way to grant temporary, narrowly-scoped access without editing the key policy directly.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('023b33a0-202f-4fed-931e-edeef91cc409', '322acd7d-9449-4896-9837-b061d3a6e376', 0, 'AWS Certificate Manager Private CA — operates a managed private certificate authority hierarchy for issuing certificates trusted WITHIN an organization''s own infrastructure (not by the public internet''s standard CA trust chain), suited to internal service-to-service TLS, private load balancers, and IoT device identity, while still offloading the operational burden of running CA infrastructure to AWS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27246b6d-06e1-4c9e-bf02-d585223a9d11', '322acd7d-9449-4896-9837-b061d3a6e376', 1, 'Public AWS Certificate Manager, since public ACM issues certificates trusted by internal-only infrastructure with no public CA trust chain involved at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd3f2c11-147d-4282-9deb-f5f68b12b8da', '322acd7d-9449-4896-9837-b061d3a6e376', 2, 'AWS Secrets Manager, since Secrets Manager''s core function is operating a private certificate authority hierarchy for internal TLS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b900519d-fad1-4454-b8dc-49d2db9800fd', '322acd7d-9449-4896-9837-b061d3a6e376', 3, 'There is no managed AWS service for issuing internally-trusted certificates; a company must always build and operate its own CA infrastructure by hand for this use case.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b503296-e0e4-41bf-9c29-5f05f9bda13b', 'e72c8ec8-59db-4cc9-9e60-a67f433cc9a1', 0, 'An allow-list SCP strategy — first detach or replace the default `FullAWSAccess` SCP (which permits everything by default) with SCPs that explicitly Allow only the specific services/actions each account/OU actually needs, so anything not explicitly allowed is implicitly denied — the inverse of the default deny-list approach of starting from full access and subtracting specific denials.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8e8727e6-01bf-4975-ba09-4580403c4b46', 'e72c8ec8-59db-4cc9-9e60-a67f433cc9a1', 1, 'This outcome is achieved by leaving the default `FullAWSAccess` SCP attached and unmodified, since that policy is defined to deny all services by default.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f63390d-46a6-42f8-805c-c07b91d60778', 'e72c8ec8-59db-4cc9-9e60-a67f433cc9a1', 2, 'A security group, since security groups control which AWS services an entire account is permitted to use across AWS Organizations.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ab0f9f0-48eb-4fa1-8fdf-ca6b8d993dac', 'e72c8ec8-59db-4cc9-9e60-a67f433cc9a1', 3, 'AWS Organizations has no mechanism to restrict which services member accounts can use; every member account always has unrestricted access to every AWS service.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('225e42c5-b2ac-45f8-bf7f-87439a1bed48', '95be5ad1-d36f-431f-9004-c305311799a4', 0, 'Requiring a unique external ID in the trust policy''s `sts:ExternalId` condition — a value only the legitimate company and the specific vendor both know, which the vendor must supply on every `AssumeRole` call, so that even if a different party learns the role''s ARN, they cannot successfully assume it without also knowing the specific external ID, directly closing the confused-deputy gap.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b009f588-8059-4717-8ab1-5198cc82879b', '95be5ad1-d36f-431f-9004-c305311799a4', 1, 'A Network ACL, since NACLs are the standard mechanism for adding an external ID requirement to a cross-account IAM role trust policy.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9754e1bd-2969-43d2-a79e-4020959ba002', '95be5ad1-d36f-431f-9004-c305311799a4', 2, 'A security group, since security groups enforce the external ID condition on STS AssumeRole calls.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39fb9605-87bf-4ead-b422-87915c324597', '95be5ad1-d36f-431f-9004-c305311799a4', 3, 'The confused-deputy risk in cross-account role assumption cannot be mitigated by any trust-policy condition; it is an unavoidable, unfixable risk of granting any third party a cross-account role.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a8a70cd-85ec-4e29-a1b0-21d305e03667', '176dd669-fbbb-4dae-9fc6-410188b870a4', 0, 'A calculated health check — combines the status of multiple CHILD health checks (each monitoring a different individual component) into one parent health check''s result, based on a configurable threshold (e.g., "healthy only if ALL children are healthy," or "healthy if at least N of M children are healthy"), giving a single overall status that reflects the true end-to-end health of a multi-component system.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87863797-de2f-46ec-969f-5f37f34c5c66', '176dd669-fbbb-4dae-9fc6-410188b870a4', 1, 'A latency-based health check, since latency-based health checks are specifically defined as combining multiple individual health checks into one overall status.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80358ecd-832f-48d0-97c8-a72cb76791b6', '176dd669-fbbb-4dae-9fc6-410188b870a4', 2, 'A CloudWatch alarm health check, since combining multiple health checks into one status is exclusively a CloudWatch alarm capability, unavailable in Route 53 itself.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc95777c-5a51-4979-a013-29eb094e6b68', '176dd669-fbbb-4dae-9fc6-410188b870a4', 3, 'Route 53 health checks can only ever monitor exactly one single endpoint each, with no way to combine multiple checks into a single overall status.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11773c7b-2622-4554-838a-85195f9dd733', '0cbc57c1-0788-47a6-8eb8-2d7a16e65387', 0, 'Multi-AZ failover is generally faster and fully automatic — RDS itself detects the primary''s failure and automatically redirects the database endpoint (via DNS) to the already-synchronized standby, typically completing within about one to two minutes with no manual intervention required, whereas promoting a read replica is a manual, deliberately-triggered action, and because replication to a read replica is asynchronous, that replica may also be missing the most recent transactions at the moment of promotion.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a8e7134-4012-4d68-b3b5-5b6f42b99f68', '0cbc57c1-0788-47a6-8eb8-2d7a16e65387', 1, 'Manually promoting a read replica is always faster than Multi-AZ automatic failover in every case, with no exception.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e09754d0-1dc7-48ad-ba4e-4df5293c0fa9', '0cbc57c1-0788-47a6-8eb8-2d7a16e65387', 2, 'Both approaches are fully automatic, provide identical recovery time, and involve zero possibility of data loss in every case.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f50696f-5ba4-4221-9910-e6643abf09d0', '0cbc57c1-0788-47a6-8eb8-2d7a16e65387', 3, 'RDS Multi-AZ deployments do not support any form of automatic failover under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f63ea725-fe3f-48d4-ba3b-e1096ad3c709', '5d6a1293-17f8-4046-90d4-869b359f8c90', 0, 'AWS Backup — a centralized backup management service that lets an organization define backup policies (schedule, retention, lifecycle to cold storage, and cross-region/cross-account copy) once, in one place, and apply them consistently across many supported AWS services (EBS, RDS, DynamoDB, EFS, and others), rather than managing each service''s backup configuration separately and inconsistently.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c8586ab-fba1-4643-a08e-a580b8502fca', '5d6a1293-17f8-4046-90d4-869b359f8c90', 1, 'AWS Config, since Config''s core function is defining centralized backup schedules and retention policies across multiple AWS services.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07ce3c8d-ffee-4c1a-b1c5-9608255970d5', '5d6a1293-17f8-4046-90d4-869b359f8c90', 2, 'AWS Trusted Advisor, since Trusted Advisor centrally manages backup schedules, retention, and cross-region copies for EBS, RDS, DynamoDB, and EFS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ca83665-8772-45dd-9c50-7b01197b7b04', '5d6a1293-17f8-4046-90d4-869b359f8c90', 3, 'No AWS service provides centralized backup management; each service''s backups must always be configured entirely separately with no shared policy mechanism.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d354e702-f59e-4d43-9895-337e62cd8b18', '7d56df9b-f65f-4db6-b12c-0176dbc8d727', 0, 'Multi-site active/active — a full-scale, continuously-running duplicate environment in a second region, ready to serve production traffic instantly with near-zero RTO/RPO; the trade-off is cost — running a fully-scaled duplicate environment continuously is significantly more expensive than a "pilot light" approach, which keeps only the smallest core infrastructure (e.g., a replicated database) running and scales the rest up only when a disaster actually occurs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8711876-00ec-4319-a7fc-db5ea239c479', '7d56df9b-f65f-4db6-b12c-0176dbc8d727', 1, 'Backup and restore, since backup and restore is defined as keeping a full-scale, continuously-running duplicate production environment active in a second region at all times.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('874151ab-c141-4d75-bfe5-85eda17abdf7', '7d56df9b-f65f-4db6-b12c-0176dbc8d727', 2, 'Pilot light, since pilot light is defined as running a fully-scaled, continuously-active duplicate of the entire production environment.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f44d37e-7be4-42d2-a099-410475fe154d', '7d56df9b-f65f-4db6-b12c-0176dbc8d727', 3, 'There is no meaningful cost difference between any DR strategy tier; every approach costs the same regardless of how much infrastructure runs continuously.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c21b663e-45a8-4ff9-90f8-4b38aa8c612c', '8a3f965f-d265-4060-b602-adaa718e414a', 0, 'AWS Elastic Disaster Recovery (AWS DRS) — continuously replicates source servers (on-premises or in another cloud) at the block level into a low-cost staging area in AWS, WITHOUT running full-sized, continuously-active recovery instances the whole time, and can launch fully-provisioned, ready-to-use recovery instances from that replicated data within minutes when an actual disaster is declared, combining low ongoing cost with a fast, low-RPO recovery capability.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0c1504b3-9fc1-4f77-9f61-5a204afe727d', '8a3f965f-d265-4060-b602-adaa718e414a', 1, 'AWS Snow Family, since Snow Family devices provide continuous, near-real-time block-level replication of on-premises servers into AWS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2996678f-71b1-4662-8cdc-9beb811643ac', '8a3f965f-d265-4060-b602-adaa718e414a', 2, 'AWS Trusted Advisor, since Trusted Advisor is the service purpose-built for continuous block-level server replication and disaster recovery launches.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78039a9d-47cf-4d54-a0f9-e952f12423e0', '8a3f965f-d265-4060-b602-adaa718e414a', 3, 'No AWS service provides continuous replication-based disaster recovery for on-premises servers; this capability does not exist.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dffcc83-1a02-4b8a-805c-b6ebe58e3889', 'e1cf9ce1-93d6-4af1-8636-2d2348945609', 0, 'EBS-optimized instances — provide dedicated, separate bandwidth specifically for EBS traffic, distinct from the instance''s general network traffic, so heavy EBS I/O doesn''t compete with (or get degraded by) the application''s regular network activity, and vice versa; many current-generation instance types provide this by default, while some require it to be explicitly enabled.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1797820c-a924-49c6-911a-4e7647d2fbaa', 'e1cf9ce1-93d6-4af1-8636-2d2348945609', 1, 'Placement groups, since placement groups provide dedicated, separate network bandwidth specifically for EBS traffic on an instance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbf759b3-e9ee-4919-894a-5ed1a9194bbd', 'e1cf9ce1-93d6-4af1-8636-2d2348945609', 2, 'Reserved Instances, since purchasing a Reserved Instance automatically provides dedicated bandwidth for EBS traffic separate from general network traffic.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52172744-caba-4d05-b841-b6bdbbace6cc', 'e1cf9ce1-93d6-4af1-8636-2d2348945609', 3, 'EBS traffic and general network traffic always share completely separate, dedicated bandwidth by default on every EC2 instance type with no configuration needed.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a312fc8c-9b6d-4bc6-85bb-aff4fc97bbe6', 'ba48d353-1733-463f-8d44-ac1de819b966', 0, 'S3 Transfer Acceleration — routes uploads (and downloads) through the nearest CloudFront edge location, then over Amazon''s own optimized backbone network to the destination bucket, instead of the public internet the whole way, typically providing a meaningful speed improvement for users geographically far from the bucket''s region, without needing to replicate or move the bucket itself.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1efba5cb-5410-4332-a2a1-669a288a1d26', 'ba48d353-1733-463f-8d44-ac1de819b966', 1, 'S3 Object Lock, since Object Lock routes uploads through CloudFront edge locations over Amazon''s optimized backbone network.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5da83628-2bda-40f5-b722-530137a4f607', 'ba48d353-1733-463f-8d44-ac1de819b966', 2, 'S3 Select, since S3 Select accelerates uploads for geographically distant users via CloudFront edge locations.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d2ce27f-e2dd-408e-8373-fa673909c7d5', 'ba48d353-1733-463f-8d44-ac1de819b966', 3, 'S3 upload speed is entirely fixed by a user''s own internet connection with no AWS-side feature able to improve it in any way.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b91e8381-b6a8-417f-a173-b0caf2447c05', '1951cc3e-462f-4201-864b-c3542651a048', 0, 'Provisioned concurrency — keeps a specified number of Lambda execution environments pre-initialized and warm at all times, ready to respond to requests with no cold-start delay, directly trading additional ongoing cost (paying to keep those environments warm even when idle) for consistently low, predictable latency on latency-sensitive workloads.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8696e714-3988-4b1d-b398-8530008fa387', '1951cc3e-462f-4201-864b-c3542651a048', 1, 'Reserved concurrency, since reserved concurrency keeps execution environments pre-initialized and warm to eliminate cold-start latency.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d720913-f4b2-40e6-8687-c620fcd582b3', '1951cc3e-462f-4201-864b-c3542651a048', 2, 'Lambda@Edge, since Lambda@Edge''s specific function is pre-initializing execution environments to eliminate cold-start delay.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6c2f9f9-1b67-4996-aff9-719cad517eac', '1951cc3e-462f-4201-864b-c3542651a048', 3, 'Cold-start latency is an unavoidable, unfixable characteristic of Lambda with no feature or configuration able to reduce or eliminate it.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a2b4851-dc87-4fb4-b60f-8220e095a676', '1396cce2-f898-42d5-9ce2-1906b2fafb2f', 0, 'Aurora Global Database — replicates an Aurora cluster across multiple AWS regions with typical replication lag under one second (using dedicated, purpose-built infrastructure separate from standard storage-level replication), providing low-latency local reads in each secondary region, and can promote a secondary region to full read/write capability in roughly one minute if the primary region fails.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('019281b5-4e84-4277-b318-0afdb80bd5fd', '1396cce2-f898-42d5-9ce2-1906b2fafb2f', 1, 'Aurora Serverless v2, since Aurora Serverless v2''s core function is replicating a database cluster across multiple AWS regions with sub-second lag.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0238855-d2d6-441b-aceb-e827a8b6ab01', '1396cce2-f898-42d5-9ce2-1906b2fafb2f', 2, 'DynamoDB Global Tables, since DynamoDB Global Tables provide cross-region replication specifically for Aurora database clusters.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc840448-bbff-4438-89f3-f8e6af7bddc8', '1396cce2-f898-42d5-9ce2-1906b2fafb2f', 3, 'Aurora does not support cross-region replication of any kind; all Aurora clusters are permanently confined to a single AWS region.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d44b290-5147-4d70-b800-4383daf7dff7', '82280465-d280-472f-9b00-77612d712c96', 0, 'An origin group — configures a primary and a secondary origin together, with CloudFront automatically routing requests to the secondary origin whenever the primary returns a configured set of failure status codes, providing automatic origin-level failover entirely within CloudFront''s own routing, with no DNS change needed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52280d83-1982-472f-b55a-983c50f44f5f', '82280465-d280-472f-9b00-77612d712c96', 1, 'Origin Shield, since Origin Shield''s core function is automatically failing over between a primary and secondary origin when the primary returns errors.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e79b5d66-89a7-4c2a-86bc-91172f931758', '82280465-d280-472f-9b00-77612d712c96', 2, 'A Route 53 failover routing policy, since Route 53 failover routing is the mechanism CloudFront itself uses internally to switch between two configured origins.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('027ace34-10b7-4838-b2a1-3c3537d2371d', '82280465-d280-472f-9b00-77612d712c96', 3, 'CloudFront distributions can only ever be configured with exactly one origin each, making automatic origin failover impossible within CloudFront itself.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9c555dfe-1ac6-4c31-8100-1aca834fb695', '642a9f17-77ad-44fb-8860-9ea86d06c577', 0, 'S3 Storage Class Analysis — observes an object set''s actual access patterns over time (typically 30+ days of observation) and produces data-driven recommendations for when objects would benefit from transitioning to a cheaper storage class like S3 Standard-IA, letting lifecycle policy decisions be based on REAL observed behavior rather than an upfront guess.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18cf0c3b-6000-4d17-bcf6-0ba9f26d58f8', '642a9f17-77ad-44fb-8860-9ea86d06c577', 1, 'S3 Intelligent-Tiering, since Storage Class Analysis and Intelligent-Tiering are the exact same feature under two different names, with no distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ce2c33c-90db-436a-afbd-5b2ace3b05a2', '642a9f17-77ad-44fb-8860-9ea86d06c577', 2, 'AWS Trusted Advisor, since Trusted Advisor is the specific feature that analyzes S3 object-level access patterns and recommends per-object storage class transitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e02842d7-6337-40d6-897a-98d99859c212', '642a9f17-77ad-44fb-8860-9ea86d06c577', 3, 'S3 provides no feature to analyze actual access patterns; storage class decisions must always be made purely from upfront guesses with no data available.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b22f671-fa1f-40ae-b525-b206036c3dcb', '48b4abcc-268b-4148-9c0c-ba4c4fcf04fc', 0, 'Convertible RIs allow exchanging the reservation for a different instance family/size/OS/tenancy combination during the term, providing flexibility as needs change, in exchange for a smaller maximum discount compared to Standard RIs — Standard RIs offer the larger discount but are LOCKED to the originally-specified configuration (with no exchange flexibility) for the full term, a direct flexibility-versus-discount trade-off between the two types.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('583ccb58-c269-409e-9c77-c263a66ce5db', '48b4abcc-268b-4148-9c0c-ba4c4fcf04fc', 1, 'Standard RIs allow exchanging the reservation for a different instance family, while Convertible RIs are permanently locked to one configuration with no exchange option.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abbc29b1-f634-4d65-8d67-4717c8366000', '48b4abcc-268b-4148-9c0c-ba4c4fcf04fc', 2, 'Both Standard and Convertible RIs provide identical exchange flexibility and identical maximum discount, with no meaningful difference between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('85d50e05-0ee0-4323-aa17-bcc8ea1a1ee9', '48b4abcc-268b-4148-9c0c-ba4c4fcf04fc', 3, 'Reserved Instances of any type can never be exchanged or modified once purchased under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b9c82c78-4c39-4516-ad9a-03f6536c4b1e', '65a34c27-6ad9-4888-b911-6349d1980e98', 0, 'Compute Savings Plans apply automatically across EC2 (any instance family/size/region), Fargate, and Lambda usage, offering broad flexibility at a somewhat lower maximum discount, while EC2 Instance Savings Plans are committed to a specific instance family within a specific region (though still flexible across size/OS/tenancy within that family), offering a higher maximum discount in exchange for that narrower scope.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3336f5ca-f208-4e25-ace3-d9c8fefa830a', '65a34c27-6ad9-4888-b911-6349d1980e98', 1, 'EC2 Instance Savings Plans apply automatically across EC2, Fargate, and Lambda usage with no restriction to any specific instance family or region.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40430a05-04da-4089-9125-92427058be2b', '65a34c27-6ad9-4888-b911-6349d1980e98', 2, 'Compute Savings Plans and EC2 Instance Savings Plans are identical in every respect, including scope and maximum discount, with no meaningful distinction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8ec5061-f19b-4a2d-b9e6-362e3f648b89', '65a34c27-6ad9-4888-b911-6349d1980e98', 3, 'Neither Savings Plan type applies to Fargate or Lambda usage under any circumstance; Savings Plans are exclusively an EC2-only mechanism.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a9a7cee-68a3-4a72-be16-3fbc64aed0b6', '87a05c18-1633-4d6e-9c7b-90bfdb24abef', 0, 'Adding a VPC Gateway Endpoint for S3 — routes traffic destined for S3 directly and privately within the AWS network, bypassing the NAT Gateway entirely for that traffic (Gateway Endpoints for S3 and DynamoDB have no additional hourly or data processing charge of their own), reducing NAT Gateway data processing costs specifically for the portion of traffic that was going to S3.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bcdd6f1d-0b35-476f-8705-094972079231', '87a05c18-1633-4d6e-9c7b-90bfdb24abef', 1, 'Purchasing a Reserved Instance, since Reserved Instances directly reduce NAT Gateway data processing charges for traffic destined to AWS services like S3.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3bbc16b-e143-4837-b7f4-a0540b35c5af', '87a05c18-1633-4d6e-9c7b-90bfdb24abef', 2, 'Enabling S3 Transfer Acceleration, since Transfer Acceleration is the mechanism that removes NAT Gateway data processing charges for traffic to S3.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75878247-8d64-42e5-984d-32e5597af255', '87a05c18-1633-4d6e-9c7b-90bfdb24abef', 3, 'NAT Gateway data processing charges apply identically to all traffic with no way to reduce them for any specific destination or traffic type.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
